// Creative format; dynamic means the platform assembles it per viewer (catalog ads).
type AdFormat string

const (
	AdFormatImage    AdFormat = "image"
	AdFormatVideo    AdFormat = "video"
	AdFormatCarousel AdFormat = "carousel"
	AdFormatText     AdFormat = "text"
	AdFormatDynamic  AdFormat = "dynamic"
)

// AllValues returns all AdFormat values.
func (AdFormat) AllValues() []AdFormat {
	return []AdFormat{
		AdFormatImage,
		AdFormatVideo,
		AdFormatCarousel,
		AdFormatText,
		AdFormatDynamic,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s AdFormat) MarshalText() ([]byte, error) {
	switch s {
	case AdFormatImage:
		return []byte(s), nil
	case AdFormatVideo:
		return []byte(s), nil
	case AdFormatCarousel:
		return []byte(s), nil
	case AdFormatText:
		return []byte(s), nil
	case AdFormatDynamic:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *AdFormat) UnmarshalText(data []byte) error {
	switch AdFormat(data) {
	case AdFormatImage:
		*s = AdFormatImage
		return nil
	case AdFormatVideo:
		*s = AdFormatVideo
		return nil
	case AdFormatCarousel:
		*s = AdFormatCarousel
		return nil
	case AdFormatText:
		*s = AdFormatText
		return nil
	case AdFormatDynamic:
		*s = AdFormatDynamic
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

