// The creator's gender as the marketplace lists it.
type CreatorGender string

const (
	CreatorGenderFemale CreatorGender = "female"
	CreatorGenderMale   CreatorGender = "male"
)

// AllValues returns all CreatorGender values.
func (CreatorGender) AllValues() []CreatorGender {
	return []CreatorGender{
		CreatorGenderFemale,
		CreatorGenderMale,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s CreatorGender) MarshalText() ([]byte, error) {
	switch s {
	case CreatorGenderFemale:
		return []byte(s), nil
	case CreatorGenderMale:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *CreatorGender) UnmarshalText(data []byte) error {
	switch CreatorGender(data) {
	case CreatorGenderFemale:
		*s = CreatorGenderFemale
		return nil
	case CreatorGenderMale:
		*s = CreatorGenderMale
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

